--
-- 0032 replaced the fifteen-limb anga pooja with the book-s twenty-four and
-- updated the instruction, but left meaning_en describing the list it had just
-- deleted -- naming Chanchala, Padmalaya and Kambukanthi at limbs those names
-- no longer occupy. The screen showed twenty-four offerings under a paragraph
-- about fifteen different ones.
--
-- Nothing caught it because meaning_en was not null, not truncated and well-
-- formed English. Same shape as the titles 0025 clobbered: the gates checked
-- the value, not whether it still described the data beside it.
--
-- Idempotent: only rewrites a meaning that still mentions the old list.
-- =============================================================================

begin;

update public.pooja_steps set
       meaning_en = 'Twenty-four names, each naming a limb, from the feet upward to the head, and a twenty-fourth for the whole body: Varalakshmi at the feet, Ksheerabdhitanaya at the thighs, Narayanapriya at the navel, Kambukanthi at the neck, Shiva at the head, and Sarvamangala for all the limbs together.',
       updated_at = now()
 where pooja_id = 'varalakshmi_vratham' and step_title_en = 'Anga Pooja'
   and (meaning_en ilike '%fifteenth%' or meaning_en ilike '%Chanchala%');

-- --- assert ------------------------------------------------------------------
do $$
declare n int; m text; rows int;
begin
  select meaning_en into m from public.pooja_steps
   where pooja_id = 'varalakshmi_vratham' and step_title_en = 'Anga Pooja';
  if m ilike '%fifteenth%' or m ilike '%Chanchala%' or m ilike '%Padmalaya%' then
    raise exception 'the anga pooja meaning still describes the replaced list'; end if;
  if m not ilike '%twenty-four%' then
    raise exception 'the anga pooja meaning does not say twenty-four'; end if;

  -- and it agrees with the rows actually stored
  select count(*) into rows from public.archana_items a
    join public.pooja_steps s on s.id = a.pooja_step_id
   where s.pooja_id = 'varalakshmi_vratham' and s.step_title_en = 'Anga Pooja';
  if rows <> 24 then
    raise exception 'the anga pooja has % rows but its meaning says twenty-four', rows; end if;

  -- every name the meaning cites is actually in the list
  select count(*) into n from public.archana_items a
    join public.pooja_steps s on s.id = a.pooja_step_id
   where s.pooja_id = 'varalakshmi_vratham' and s.step_title_en = 'Anga Pooja'
     and a.invoked_name_deva like '%वरलक्ष्म्यै%';
  if n < 1 then raise exception 'the meaning cites Varalakshmi, which is not in the list'; end if;
  select count(*) into n from public.archana_items a
    join public.pooja_steps s on s.id = a.pooja_step_id
   where s.pooja_id = 'varalakshmi_vratham' and s.step_title_en = 'Anga Pooja'
     and a.invoked_name_deva like '%क्षीराब्धि%';
  if n < 1 then raise exception 'the meaning cites Ksheerabdhitanaya, which is not in the list'; end if;
  select count(*) into n from public.archana_items a
    join public.pooja_steps s on s.id = a.pooja_step_id
   where s.pooja_id = 'varalakshmi_vratham' and s.step_title_en = 'Anga Pooja'
     and a.invoked_name_deva like '%नारायण%';
  if n < 1 then raise exception 'the meaning cites Narayanapriya, which is not in the list'; end if;
  select count(*) into n from public.archana_items a
    join public.pooja_steps s on s.id = a.pooja_step_id
   where s.pooja_id = 'varalakshmi_vratham' and s.step_title_en = 'Anga Pooja'
     and a.invoked_name_deva like '%कम्बुकण्ठ्यै%';
  if n < 1 then raise exception 'the meaning cites Kambukanthi, which is not in the list'; end if;
  select count(*) into n from public.archana_items a
    join public.pooja_steps s on s.id = a.pooja_step_id
   where s.pooja_id = 'varalakshmi_vratham' and s.step_title_en = 'Anga Pooja'
     and a.invoked_name_deva like '%शिवायै%';
  if n < 1 then raise exception 'the meaning cites Shiva, which is not in the list'; end if;
  select count(*) into n from public.archana_items a
    join public.pooja_steps s on s.id = a.pooja_step_id
   where s.pooja_id = 'varalakshmi_vratham' and s.step_title_en = 'Anga Pooja'
     and a.invoked_name_deva like '%सर्वमङ्गलायै%';
  if n < 1 then raise exception 'the meaning cites Sarvamangala, which is not in the list'; end if;
end $$;


